-- Enable Row Level Security on all relevant tables
alter table public.teams enable row level security;
alter table public.team_members enable row level security;
alter table public.documents enable row level security;

-- R1: Users can see the teams they belong to
create policy "Users can see their own teams" on public.teams
for select using (exists (
  select 1 from public.team_members
  where team_members.team_id = teams.id
  and team_members.user_id = auth.uid()
));

-- R2: Users can see their own membership rows only
create policy "Users can see own memberships" on public.team_members
for select using (user_id = auth.uid());

-- R3: Team members can read team's documents except deleted
create policy "Team members can read active documents" on public.documents
for select using (team_id in (
  select team_id from public.team_members
  where user_id = auth.uid()
) and deleted_at is null);

-- R4: Editors can create documents, recorded as created by themselves
create policy "Editors can create documents" on public.documents
for insert with check (exists (
  select 1 from public.team_members
  where team_id = team_id  -- references the team being inserted into
  and user_id = auth.uid()
  and role = 'editor'
));

-- R5: Editors can edit any document in their teams
create policy "Editors can edit documents in their team" on public.documents
for update using (exists (
  select 1 from public.team_members
  where team_id = documents.team_id
  and user_id = auth.uid()
  and role = 'editor'
));

-- R6: Only the creator can delete a document
create policy "Only creator can delete document" on public.documents
for delete using (created_by = auth.uid());

-- R7: Teams and memberships cannot be modified by users (no insert/update/delete policies created)

-- R8: Anonymous visitors cannot see or change anything (handled by RLS default deny)

-- R9: Server-side code using service role keeps full access (implicitly via service_role bypass)

-- Grant usage of auth.uid() to authenticated users (implicit, but explicit for clarity)
grant usage on schema public to authenticated;
