alter table public.team_members enable row level security;
alter table public.documents enable row level security;

-- R1: Users can see the teams they belong to
create policy "Users can see their own teams" on public.teams
for select using (exists (
  select 1 from public.team_members
  where team_id = id and user_id = auth.uid()
));

-- R2: Users can see their own membership rows only
create policy "Users can see own memberships" on public.team_members
for select using (user_id = auth.uid());

-- R3: Team members can read team's documents except deleted ones
create policy "Team members can read active documents" on public.documents
for select using (
  team_id in (
    select team_id from public.team_members
    where user_id = auth.uid()
  ) and deleted_at is null
);

-- R4: Editors can create documents, recorded as created by themselves
create policy "Editors can create documents" on public.documents
for insert with check (
  auth.uid() = created_by and
  exists (
    select 1 from public.team_members
    where team_id = team_id and user_id = auth.uid() and role = 'editor'
  )
);

-- R5: Editors can edit any document in their teams; document must stay in an editor-accessible team
create policy "Editors can edit documents" on public.documents
for update using (
  exists (
    select 1 from public.team_members
    where team_id = team_id and user_id = auth.uid() and role = 'editor'
  )
) with check (
  -- The update must not change team_id to a team where user is not an editor
  (team_id is null or team_id = old.team_id) or
  exists (
    select 1 from public.team_members
    where team_id = new.team_id and user_id = auth.uid() and role = 'editor'
  )
);

-- R6: Only the creator can delete a document
create policy "Only creator can delete documents" on public.documents
for delete using (auth.uid() = created_by);

-- R7: Teams and memberships cannot be modified by users (only service_role)
-- No policies needed on teams/table_members for insert/update/delete as they are restricted by the absence of user policies,
-- but we explicitly deny user modifications by creating restrictive policies that effectively block them.

-- Block user inserts into teams
create policy "Prevent user insert into teams" on public.teams
for insert to authenticated with check (false);

-- Block user updates to teams
create policy "Prevent user update teams" on public.teams
for update to authenticated using (false) with check (false);

-- Block user deletes from teams
create policy "Prevent user delete teams" on public.teams
for delete to authenticated using (false);

-- Block user inserts into team_members
create policy "Prevent user insert team_members" on public.team_members
for insert to authenticated with check (false);

-- Block user updates to team_members
create policy "Prevent user update team_members" on public.team_members
for update to authenticated using (false) with check (false);

-- Block user deletes from team_members
create policy "Prevent user delete team_members" on public.team_members
for delete to authenticated using (false);

-- R8: Anonymous visitors cannot see or change anything
-- By default, anon role has no access when RLS is enabled and no public policies allow anon.
-- The policies above are for authenticated users only.

-- R9: Server-side code using service_role keeps full access
-- service_role bypasses RLS by default; no additional action needed.

-- Grants: Ensure authenticated users can use the tables (policies handle access, but sequences etc may need grants)
grant usage on schema public to authenticated;
grant all on public.teams to service_role;
grant all on public.team_members to service_role;
grant all on public.documents to service_role;

-- Optional: Grant select on teams to anon if R1 is intended for anon, but R8 says anon cannot see anything.
-- Leaving anon without access per R8.
