-- Enable RLS on tables
alter table public.invoices enable row level security;
alter table public.finance_staff enable row level security;

-- R1: Read access
-- Users can read their own invoices
create policy "Users can read own invoices" on public.invoices
  for select using (created_by = auth.uid());

-- Finance staff can read every invoice
create policy "Finance staff can read all invoices" on public.invoices
  for select using (exists (select 1 from public.finance_staff where user_id = auth.uid()));

-- R2: Create access
-- Users can create invoices only as themselves and only as drafts
create policy "Users can create draft invoices only" on public.invoices
  for insert with check (
    created_by = auth.uid() 
    and status = 'draft'
  );

-- R3 & R4: Update access via helper function
create or replace function public.invoice_update_policy()
returns trigger language plpgsql as $$
begin
  -- Get current user id and check if finance staff
  declare
    v_user_id uuid := auth.uid();
    v_is_staff boolean;
  begin
    select exists(select 1 from public.finance_staff where user_id = v_user_id) into v_is_staff;

    -- R9: Service role bypass (called from server-side)
    if current_setting('role') = 'service_role' then
      return new;
    end if;

    -- Row-level rules
    if (TG_OP = 'UPDATE') then
      -- R6: Nobody can change created_by
      if (new.created_by is distinct from old.created_by) then
        return null; -- reject change
      end if;

      -- R5 & R3: Deletion and draft-only changes handled at trigger level or policy
      -- Check if invoice is a draft
      if (old.status = 'draft') then
        -- R3: Creator of draft can change customer, amount, and status to 'sent'
        if (v_is_staff) then
          -- R4: Finance staff can only change status to 'paid' or 'void' from 'sent'
          -- (This is enforced by R4 policy below, but kept here for consistency)
          if (new.status in ('paid', 'void')) then
            return new;
          end if;
        else
          -- Regular user: can change customer and amount, and status from draft to sent
          if (new.status = 'sent') then
            -- Allow customer and amount changes
            return new;
          elsif (new.status = old.status) then
            -- No status change, allowed (form sends all fields)
            return new;
          else
            -- Other status changes from draft rejected
            return null;
          end if;
        end if;
      else
        -- Invoice is not a draft (sent, paid, void)
        if (v_is_staff) then
          -- R4: Finance staff can change status from 'sent' to 'paid' or 'void'
          -- No other status changes allowed for finance staff from non-draft state
          if (old.status = 'sent' and new.status in ('paid', 'void')) then
            return new;
          else
            -- No other status changes allowed
            return null;
          end if;
        else
          -- Regular user: no changes allowed on non-draft invoices
          return null;
        end if;
      end if;
    end if;

    return new;
  end;
end;
$$;

-- R3 & R4: Apply update policy via trigger
create trigger "invoice_update_trigger"
  after update on public.invoices
  for each row execute function public.invoice_update_policy();

-- R5: Delete access
-- Creators can delete their own draft invoices
create policy "Creators can delete own draft invoices" on public.invoices
  for delete using (
    created_by = auth.uid() 
    and old.status = 'draft'
  );

-- R6: Already covered by trigger (created_by check)

-- R7: Finance staff visibility
-- Users can see if they are finance staff
create policy "Users can see own finance staff status" on public.finance_staff
  for select using (user_id = auth.uid());

-- R8: Anonymous access denied (default RLS behavior blocks anon without explicit policy)
-- No policies needed; RLS blocks anon by default

-- R9: Service role grants (implicit via role check in function)
-- Grant service_role full access on invoices (bypasses RLS)
grant all on public.invoices to service_role;
grant all on public.finance_staff to service_role;

-- Grant authenticated users basic permissions
grant select, insert (with check (created_by = auth.uid())) on public.invoices to authenticated;
grant select on public.finance_staff to authenticated;
