      where restaurant_id = restaurant_id
        and user_id = auth.uid()
    )
  );

-- R2: Guests can book, as themselves, only for a time in the future, and new reservations are always booked
create policy "Guests can create future reservations" on public.reservations
  for insert with check (
    auth.uid() = user_id
    and reserved_for > now()
    and status = 'booked'
  );

-- R3: Guests can cancel their own booked reservations while the reservation time is still in the future
create policy "Guests can cancel own future booked reservations" on public.reservations
  for update using (
    auth.uid() = user_id
    and status = 'booked'
    and reserved_for > now()
  )
  with check (
    auth.uid() = user_id
    and status = 'cancelled'
    and reserved_for > now()
  );

-- R4: Staff can mark booked reservations at their restaurant as seated or no_show, but only once the reservation time has passed
create policy "Staff can update reservation status after time" on public.reservations
  for update using (
    exists (
      select 1 from public.restaurant_staff
      where restaurant_id = restaurant_id
        and user_id = auth.uid()
    )
    and reserved_for <= now()
  )
  with check (
    exists (
