-- Helper function to check if current user is admin of a given org
create function public.is_org_admin(org_id bigint) returns boolean language sql as $$
  select exists (
    select 1 from public.org_members
    where org_id = is_org_admin.org_id
    and user_id = auth.uid()
    and role = 'admin'
  );
$$;

-- R1: Members can see their organizations and every member of those organizations
create policy "Members can see orgs and members" on public.orgs
  for select using (auth.role() = 'authenticated');

create policy "Members can see org members" on public.org_members
  for select using (auth.role() = 'authenticated');

-- R2: Only admins can manage invites for their organization
-- Create invite (admin only)
create policy "Admins can create invites" on public.invites
  for insert with check (
    auth.role() = 'authenticated'
    and exists (
      select 1 from public.org_members
      where org_id = invites.org_id
      and user_id = auth.uid()
      and role = 'admin'
    )
  );

-- Read invites: only via token (accept_invite path), nobody else can read
create policy "Invites readable by token only" on public.invites
  for select using (false); -- No public select; access only through accept_invite RPC

-- Update invite (admin only, e.g., revoke)
create policy "Admins can update invites" on public.invites
  for update using (
    auth.role() = 'authenticated'
    and exists (
      select 1 from public.org_members
      where org_id = invites.org_id
      and user_id = auth.uid()
      and role = 'admin'
    )
  )
  with check (
    auth.role() = 'authenticated'
    and exists (
      select 1 from public.org_members
      where org_id = invites.org_id
      and user_id = auth.uid()
      and role = 'admin'
    )
  );

-- Delete invite (admin only)
create policy "Admins can delete invites" on public.invites
  for delete using (
    auth.role() = 'authenticated'
    and exists (
      select 1 from public.org_members
      where org_id = invites.org_id
      and user_id = auth.uid()
      and role = 'admin'
    )
  );

-- R3: accept_invite RPC
-- Drop if exists to ensure clean state
drop function if public.accept_invite(text);

create function public.accept_invite(p_token text) returns bigint language sql strict as $$
declare
  v_org_id bigint;
  v_invite_role text;
  v_invite_email text;
  v_caller_email text;
begin
  -- 1. Must be signed in
  if auth.uid() is null then
    raise exception 'User not signed in';
  end if;

  -- 2. Token must exist and not be accepted yet
  select org_id, role, email, expires_at, accepted_at
  into v_org_id, v_invite_role, v_invite_email, expires_at, accepted_at
  from public.invites
  where token = p_token;

  if not found then
    raise exception 'Invalid or unknown token';
  end if;

  if accepted_at is not null then
    raise exception 'Invite already accepted';
  end if;

  -- 3. Invite must not be expired
  if expires_at < now() then
    raise exception 'Invite has expired';
  end if;

  -- 4. Email must match caller's verified email (case-insensitive)
  -- Supabase puts verified email in JWT claim `email`
  v_caller_email = lower(coalesce(auth.jwt()->>'email', ''));
  if lower(v_invite_email) != v_caller_email then
    raise exception 'Invite email does not match caller verified email';
  end if;

  -- 5. Add user to org_members with the invite's role
  insert into public.org_members (org_id, user_id, role)
  values (v_org_id, auth.uid(), v_invite_role);

  -- 6. Mark invite as accepted
  update public.invites
  set accepted_at = now()
  where token = p_token;

  return v_org_id;
end;
$$;

-- R4: Apart from accept_invite, nobody can add or change memberships or organizations
-- (Already covered by R1/R2 policies restricting insert/update/delete on orgs/org_members)
-- Ensure no accidental inserts/updates via public paths are allowed without being admin
-- (The policies above already restrict to admins only; service_role bypasses RLS)

-- R5: Anonymous visitors cannot see or change anything
-- The policies with auth.role() = 'authenticated' already block anon.
-- Additionally, we can add a deny for anon role explicitly if needed, but the select using (auth.role() = 'authenticated') is sufficient.

-- R6: Server-side code using the service role keeps full access
-- Supabase handles this: service_role bypasses RLS automatically.

-- Grants: ensure authenticated users can use the function
grant execute on public.accept_invite to authenticated;

-- Revokes: remove public access if any (defense in depth)
revoke all on public.orgs from public;
revoke all on public.org_members from public;
revoke all on public.invites from public;
