alter table public.location_staff enable row level security;
alter table public.stock enable row level security;

-- Helper function to check if current user is an auditor
create or replace function public.is_auditor()
returns boolean language sql security invoker as $$
  select exists (
    select 1 from auth.jwt() j
    where (j->>'app_metadata')::jsonb ? 'role'
    and (j->'app_metadata'->>'role')::text = 'auditor'
  );
$$;

-- Helper function to check if current user is staff at a given location
create or replace function public.is_staff_at_location(location_id bigint)
returns boolean language sql security invoker as $$
  select exists (
    select 1 from public.location_staff ls
    where ls.location_id = location_id
    and ls.user_id = auth.uid()
  );
$$;

-- R1: Signed-in users can see locations; Staff see their own location stock/staff; Auditors see all
create policy "R1_locations_select" on public.locations
  for select using ( auth.role() = 'authenticated' );

