  for insert with check ( auth.role() = 'authenticated' and public.is_staff_at_location(location_id) );

create policy "R2_stock_update" on public.stock
  for update using ( auth.role() = 'authenticated' and public.is_staff_at_location(location_id) )
    with check ( auth.role() = 'authenticated' and public.is_staff_at_location(location_id) );

