```sql
-- Enable Row Level Security on all relevant tables
alter table public.projects enable row level security;
alter table public.project_members enable row level security;
alter table public.issues enable row level security;

-- Helper function: check if user is a maintainer of a given project
create function public.is_maintainer(project_id bigint, user_id uuid)
returns boolean language sql security definer as $$
  select exists (
    select 1 from public.project_members
    where project_id = is_maintainer.project_id
    and user_id = is_maintainer.user_id
    and role = 'maintainer'
  );
$$;

-- Helper function: check if user is a reporter or maintainer of a given project
create function public.is_reporter_or_maintainer(project_id bigint, user_id uuid)
returns boolean language sql security definer as $$
  select exists (
    select 1 from public.project_members
    where project_id = is_reporter_or_maintainer.project_id
    and user_id = is_reporter_or_maintainer.user_id
    and role in ('reporter', 'developer', 'maintainer')
  );
$$;

-- Helper function: check if user can update a given issue (maintainer or assignee)
create function public.can_update_issue(project_id bigint, issue_id bigint, user_id uuid)
returns boolean language sql security definer as $$
  select exists (
    select 1 from public.project_members pm
    join public.issues i on i.project_id = pm.project_id
    where pm.project_id = project_id
    and pm.user_id = user_id
    and pm.role in ('developer', 'maintainer')
    and i.id = issue_id
    and (
      i.is_confidential = false
      or pm.role = 'maintainer'
      or i.reporter_id = user_id
      or i.assignee_id = user_id
    )
  );
$$;

-- Projects: allow authenticated members to see their projects and all members
create policy "project_members_select" on public.projects
for select to authenticated
using (
  exists (
    select 1 from public.project_members
    where project_id = id
    and user_id = auth.uid()
  )
);

-- Project members: allow authenticated members to see their project memberships
create policy "project_members_select" on public.project_members
for select to authenticated
using (user_id = auth.uid() or exists (
  select 1 from public.project_members pm2
  where pm2.project_id = project_id
  and pm2.user_id = auth.uid()
));

-- Issues: members can see every non-confidential issue in their projects;
-- confidential issues visible only to maintainers, reporter, and assignee
create policy "issues_select" on public.issues
for select to authenticated
using (
  project_id in (
    select project_id from public.project_members
    where user_id = auth.uid()
  )
  and (
    not is_confidential
    or exists (
      select 1 from public.project_members pm
      where pm.project_id = issues.project_id
      and pm.user_id = auth.uid()
      and pm.role = 'maintainer'
    )
    or reporter_id = auth.uid()
    or assignee_id = auth.uid()
  )
);

-- Issues: developers and maintainers can update issues they can see;
-- only maintainers can toggle confidentiality
create policy "issues_update" on public.issues
for update to authenticated
using (can_update_issue(project_id, id, auth.uid()))
with check (
  can_update_issue(project_id, id, auth.uid())
  and (
    not new.is_confidential
    or is_maintainer(project_id, auth.uid())
  )
);

