-- Enable RLS on all relevant tables
alter table public.projects enable row level security;
alter table public.translators enable row level security;
alter table public.segments enable row level security;

-- Helper function to check if user is assigned to a project as translator or reviewer for a given language
create function public.is_assigned_to_project(p_project_id bigint, p_lang text, p_user_id uuid)
returns boolean language sql security invoker
as $$
  select exists (
    select 1 from public.translators
    where project_id = p_project_id
      and lang = p_lang
      and user_id = p_user_id
      and role in ('translator', 'reviewer')
  );
$$;

-- Helper function to check if user is a reviewer for a project/language
create function public.is_reviewer_of_project(p_project_id bigint, p_lang text, p_user_id uuid)
returns boolean language sql security invoker
as $$
  select exists (
    select 1 from public.translators
    where project_id = p_project_id
      and lang = p_lang
      and user_id = p_user_id
      and role = 'reviewer'
  );
$$;

-- Helper function to check if segment is in draft status
create function public.is_draft_segment(p_segment_id bigint)
returns boolean language sql security invoker
as $$
  select exists (
    select 1 from public.segments
    where id = p_segment_id
      and status = 'draft'
  );
$$;

-- RLS Policies for projects
create policy "Projects: view assigned projects" on public.projects
  for select using (
    exists (
      select 1 from public.translators
      where project_id = id
        and user_id = auth.uid()
        and role in ('translator', 'reviewer')
    )
  );

-- RLS Policies for translators (assignment table)
create policy "Translators: view own assignments" on public.translators
  for select using (user_id = auth.uid());

create policy "Translators: insert own assignments" on public.translators
  for insert with check (user_id = auth.uid());

-- RLS Policies for segments
-- R1: Users can see segments of languages they are assigned to
create policy "Segments: view assigned languages" on public.segments
  for select using (
    exists (
      select 1 from public.translators t
      where t.project_id = project_id
        and t.lang = lang
        and t.user_id = auth.uid()
        and t.role in ('translator', 'reviewer')
    )
  );

-- R2: Translators can edit draft segments in their language, recording themselves
create policy "Translators: update draft segments" on public.segments
  for update using (
    is_draft_segment(id) 
    and exists (
      select 1 from public.translators t
      where t.project_id = project_id
        and t.lang = lang
        and t.user_id = auth.uid()
        and t.role = 'translator'
    )
  )
  with check (
    -- Always record the translator in translated_by
    (translated_by = auth.uid() or translated_by is null)
    -- Source text must not change
    and source_text = old.source_text
  );

-- R3: Reviewers can mark draft segments reviewed (and may correct translation)
create policy "Reviewers: mark reviewed" on public.segments
  for update using (
    is_draft_segment(id)
    and exists (
      select 1 from public.translators t
      where t.project_id = project_id
        and t.lang = lang
        and t.user_id = auth.uid()
        and t.role = 'reviewer'
    )
  )
  with check (
    status = 'reviewed'
    -- Reviewers may correct target_text
    and target_text is distinct from old.target_text or true
    -- Source text must not change
    and source_text = old.source_text
  );

-- R4: Reviewed segments can no longer be changed by the app
-- This is enforced by the with check clauses above: if status = 'reviewed', 
-- the update policies will reject changes. Additionally, we add a check 
-- to prevent updates on reviewed segments at the row level for safety.
create policy "Segments: protect reviewed segments" on public.segments
  for update using (
    not (status = 'reviewed')
  )
  with check (
    not (status = 'reviewed')
  );

-- R5: Anonymous visitors cannot see or change anything
-- The policies above already restrict to authenticated users via auth.uid().
-- No additional policy needed as anon has no role and auth.uid() returns null.

-- R6: Server-side code using service role keeps full access
-- service_role bypasses RLS by default in Supabase, no additional policy needed.

-- Grant usage on helper functions to authenticated users if needed
grant usage on function public.is_assigned_to_project(bigint, text, uuid) to authenticated;
grant usage on function public.is_reviewer_of_project(bigint, text, uuid) to authenticated;
grant usage on function public.is_draft_segment(bigint) to authenticated;

-- Revoke public access to tables to ensure anon cannot bypass
revoke all on public.projects from public;
revoke all on public.translators from public;
revoke all on public.segments from public;
