  v_sender_id uuid;
  v_status text;
  v_order integer;
  v_signed_count integer;
  v_earlier_signed boolean;
begin
  -- Ensure the caller is a recipient of this envelope
  if not exists (
    select 1 from public.envelope_recipients
    where envelope_id = p_envelope_id
      and user_id = auth.uid()
  ) then
    raise exception 'Caller is not a recipient of this envelope';
  end if;

