  ) then
    raise exception 'Caller has already signed this envelope';
  end if;

  -- Get the sign_order for the caller
  select sign_order into v_order
  from public.envelope_recipients
  where envelope_id = p_envelope_id
    and user_id = auth.uid();

  -- Check that all earlier recipients have signed
  select count(*) into v_signed_count
  from public.envelope_recipients
  where envelope_id = p_envelope_id
    and sign_order < v_order
    and signed_at is not null;

  if v_signed_count = 0 then
    raise exception 'An earlier recipient in sign_order has not signed yet';
  end if;

