-- RPC: sign_envelope
-- Records the caller's signature, validates sign_order, envelope status, and that prior recipients have signed.
-- Returns the envelope's status afterwards.
create or replace function public.sign_envelope(p_envelope_id bigint) returns text language plpgsql security invoker as $$
declare
  v_sender_id uuid;
  v_signer_id uuid;
  v_sign_order integer;
  v_prev_signed boolean;
  v_all_signed boolean;
begin
  -- 1. Resolve the caller's user_id from the JWT
  v_signer_id := auth.uid();

  -- 2. Validate envelope exists and is in 'sent' state
  if not exists (select 1 from public.envelopes where id = p_envelope_id and status = 'sent') then
    raise exception 'Envelope is not in ''sent'' state';
  end if;

  -- 3. Check that the caller is a recipient of this envelope and get their sign_order
  select e.sender_id, er.sign_order
  into v_sender_id, v_sign_order
  from public.envelopes e
  join public.envelope_recipients er on er.envelope_id = e.id
  where e.id = p_envelope_id
    and er.user_id = v_signer_id;

  if not found then
    raise exception 'Caller is not a recipient of this envelope';
  end if;

  -- 4. Check that the caller has not already signed
  if exists (select 1 from public.envelope_recipients
             where envelope_id = p_envelope_id
               and user_id = v_signer_id
               and signed_at is not null) then
    raise exception 'Caller has already signed this envelope';
  end if;

  -- 5. Check that all earlier sign_order recipients have signed
  select exists (select 1 from public.envelope_recipients
                 where envelope_id = p_envelope_id
                   and sign_order < v_sign_order
                   and signed_at is null) into v_prev_signed;

  if v_prev_signed then
    raise exception 'An earlier recipient in sign_order has not signed yet';
  end if;

  -- 6. Record the signature
  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id
    and user_id = v_signer_id;

  -- 7. Check if every recipient has now signed
  select public.everyone_signed(p_envelope_id) into v_all_signed;

  if v_all_signed then
    update public.envelopes
    set status = 'completed'
    where id = p_envelope_id;
  end if;

  -- 8. Return the current status
  return (select status from public.envelopes where id = p_envelope_id);
end;
$$;

-- RPC: void_envelope
-- Lets the sender cancel an envelope that is still 'sent'.
-- Returns the envelope's status afterwards.
create or replace function public.void_envelope(p_envelope_id bigint) returns text language plpgsql security invoker as $$
declare
  v_sender_id uuid;
  v_status text;
begin
  -- 1. Resolve the caller's user_id
  v_sender_id := auth.uid();

  -- 2. Validate envelope exists and is owned by the caller and is in 'sent' state
  if not exists (select 1 from public.envelopes
                 where id = p_envelope_id
                   and sender_id = v_sender_id
                   and status = 'sent') then
    raise exception 'Envelope is not in ''sent'' state or you are not the sender';
  end if;

  -- 3. Void the envelope
  update public.envelopes
  set status = 'voided'
  where id = p_envelope_id;

  -- 4. Return the current status
  return (select status from public.envelopes where id = p_envelope_id);
end;
$$;

-- Grant usage of the RPC functions to authenticated users (anon cannot call them)
grant execute on public.sign_envelope to authenticated;
grant execute on public.void_envelope to authenticated;

-- Ensure service_role bypasses RLS (already default, but explicit grant for clarity)
grant all on public.envelopes to service_role;
grant all on public.envelope_recipients to service_role;

-- Revoke public access to tables to enforce RLS
revoke all on public.envelopes from public;
revoke all on public.envelope_recipients from public;
