  select count(*) into v_signed_count
  from public.envelope_recipients
  where envelope_id = p_envelope_id
    and sign_order < v_order
    and signed_at is not null;

  if v_signed_count = 0 then
    raise exception 'An earlier recipient in sign_order has not signed yet';
  end if;

  -- Record the signature
  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id
    and user_id = auth.uid();

  -- Check if everyone has now signed
  if public.everyone_signed(p_envelope_id) then
    update public.envelopes
    set status = 'completed'
    where id = p_envelope_id;
  end if;

  -- Return the current status
  select status into v_status
  from public.envelopes
  where id = p_envelope_id;

  return v_status;
end;
$$;

-- RPC: void_envelope - lets the sender cancel an envelope that is still 'sent'
create or replace function public.void_envelope(p_envelope_id bigint) returns text language sql strict as $$
declare
  v_status text;
  v_sender_id uuid;
begin
  -- Lock the envelope row
  select status, sender_id into v_status, v_sender_id
  from public.envelopes
  where id = p_envelope_id
  for update;

  -- Only the sender can void
  if v_sender_id != auth.uid() then
    raise exception 'Only the sender can void this envelope';
  end if;

  -- Only envelopes with status 'sent' can be voided
  if v_status != 'sent' then
    raise exception 'Envelope is not in ''sent'' status and cannot be voided';
  end if;

  -- Void the envelope
  update public.envelopes
  set status = 'voided'
  where id = p_envelope_id;

  -- Return the new status
  return 'voided';
end;
$$;

-- Grant execute rights to authenticated users for the RPCs
grant execute on function public.sign_envelope(bigint) to authenticated;
grant execute on function public.void_envelope(bigint) to authenticated;

-- Ensure service_role retains full access (implicit via set_role, but explicit grant for clarity)
grant all on public.envelopes to service_role;
grant all on public.envelope_recipients to service_role;
grant usage on schema public to service_role;
