create or replace function public.sign_envelope(p_envelope_id bigint) returns text language plpgsql security definer as $$
declare
  v_sender_id uuid;
  v_status text;
  v_already_signed boolean;
  v_not_sent boolean;
  v_earlier_unsigned boolean;
  v_caller_is_recipient boolean;
begin
  -- Verify envelope exists and get sender
  select sender_id, status into v_sender_id, v_status
  from public.envelopes
  where id = p_envelope_id;

  if not found then
    raise exception 'Envelope not found';
  end if;

  -- R5: anonymous visitors cannot sign
  if auth.role() = 'anon' then
    raise exception 'Anonymous users cannot sign';
  end if;

  -- R3: caller must be a recipient
  select count(*) > 0 into v_caller_is_recipient
  from public.envelope_recipients
  where envelope_id = p_envelope_id
    and user_id = auth.uid();

  if not v_caller_is_recipient then
    raise exception 'You are not a recipient of this envelope';
  end if;

  -- R3: envelope must be in 'sent' status
  if v_status != 'sent' then
    raise exception 'Envelope is not in sent status';
  end if;

  -- R3: caller must not have already signed
  select count(*) > 0 into v_already_signed
  from public.envelope_recipients
  where envelope_id = p_envelope_id
    and user_id = auth.uid()
    and signed_at is not null;

  if v_already_signed then
    raise exception 'You have already signed this envelope';
  end if;

  -- R3: every earlier sign_order must have signed
  select bool_and(rr.signed_at is not null) into v_earlier_unsigned
  from public.envelope_recipients rr
  where rr.envelope_id = p_envelope_id
    and rr.sign_order < (
      select sign_order from public.envelope_recipients
      where envelope_id = p_envelope_id
        and user_id = auth.uid()
    );

  if not v_earlier_unsigned then
    raise exception 'An earlier recipient in sign_order has not signed yet';
  end if;

  -- Record the signature
  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id
    and user_id = auth.uid();

  -- Check if everyone signed
  if public.everyone_signed(p_envelope_id) then
    update public.envelopes
    set status = 'completed'
    where id = p_envelope_id;
  end if;

  -- Return current status
  select status into v_status from public.envelopes where id = p_envelope_id;
  return v_status;
end;
$$;

