  -- Verify envelope exists and get sender
  select sender_id, status into v_sender_id, v_status
  from public.envelopes
  where id = p_envelope_id;

  if not found then
    raise exception 'Envelope not found';
  end if;

  -- R5: anonymous visitors cannot void
  if auth.role() = 'anon' then
    raise exception 'Anonymous users cannot void envelopes';
  end if;

  -- R4: only the sender can void
  if auth.uid() != v_sender_id then
    raise exception 'Only the sender can void this envelope';
  end if;

  -- R4: envelope must be in 'sent' status
  if v_status != 'sent' then
    raise exception 'Envelope is not in sent status and cannot be voided';
  end if;

  -- Void the envelope
  update public.envelopes
  set status = 'voided'
  where id = p_envelope_id;

  -- Return current status
  select status into v_status from public.envelopes where id = p_envelope_id;
  return v_status;
end;
$$;

