  for select using (auth.role() = 'service_role' or user_id = auth.uid());

create policy "org_admins_insert" on public.org_admins
  for insert with check (auth.role() = 'service_role');

-- RLS Policies for devices
create policy "devices_select_employee" on public.devices
  for select using (
    auth.role() = 'service_role' or
    assigned_to = auth.uid() or
    exists (select 1 from public.org_admins where org_id = public.devices.org_id and user_id = auth.uid())
  );

create policy "devices_insert_admin" on public.devices
  for insert with check (auth.role() = 'service_role');

-- RLS Policies for device_commands
-- R1: Employees see own devices and commands; IT admins see all devices/commands of their org
create policy "device_commands_select_employee" on public.device_commands
  for select using (
    auth.role() = 'service_role' or
    exists (
      select 1 from public.devices d
      where d.id = device_id
        and (d.assigned_to = auth.uid() or
             exists (select 1 from public.org_admins oa where oa.org_id = d.org_id and oa.user_id = auth.uid()))
    )
  );

-- R2: IT admins can issue any command to their organization's devices, as themselves
create policy "device_commands_insert_admin" on public.device_commands
  for insert with check (
    auth.role() = 'service_role' or
    (auth.uid() = issued_by and
     exists (
       select 1 from public.devices d
       where d.id = device_id
         and exists (select 1 from public.org_admins oa where oa.org_id = d.org_id and oa.user_id = auth.uid())
     ))
  );

-- R3: Employees can issue only `locate` and `lock`, as themselves, only to devices assigned to them
create policy "device_commands_insert_employee" on public.device_commands
  for insert with check (
    auth.role() = 'service_role' or
    (auth.uid() = issued_by and
     command in ('locate', 'lock') and
     exists (
       select 1 from public.devices d
       where d.id = device_id
         and d.assigned_to = auth.uid()
     ))
  );

-- R4: No updates or deletes ever
create policy "device_commands_no_update" on public.device_commands
  for update using (false) with check (false);

create policy "device_commands_no_delete" on public.device_commands
  for delete using (false);

-- R5: Anonymous visitors cannot see or change anything
-- (RLS default behavior: no policy = no access for anon; explicit deny not needed)

-- R6: Server-side code using the service role keeps full access
-- (service_role bypasses RLS by default; no additional grant needed)

-- Grants for authenticated users (employees and admins) to insert their own commands
grant insert (device_id, command, issued_by) on public.device_commands to authenticated;
-- Allow employees to select their own devices and commands
grant select on public.devices to authenticated;
grant select on public.device_commands to authenticated;
-- Admins need broader access; handled by policies above
-- Revoke public access to be safe
revoke all on public.org_admins from public;
revoke all on public.devices from public;
revoke all on public.device_commands from public;
