  on public.profiles for select
  using (visibility = 'members' and auth.role() = 'authenticated');

-- R3: Users can create, update, delete only their own profile
-- Create function to validate ownership
create or replace function public.own_profile()
returns trigger as $$
begin
  -- Allow insert only if user_id matches the authenticated user
  if (TG_OP = 'INSERT') then
    new.user_id = auth.uid();
    return new;
  end if;
  -- Allow update only if user_id matches the authenticated user
  if (TG_OP = 'UPDATE') then
    new.user_id = old.user_id; -- Prevent changing user_id
    new.id = old.id;           -- Prevent changing id
    return new;
  end if;
  -- Allow delete only if user_id matches the authenticated user
  if (TG_OP = 'DELETE') then
    return old;
  end if;
  return null;
end;
$$ language plpgsql security definer;

-- Attach the ownership trigger
create trigger own_profile
  before insert or update or delete on public.profiles
  for each row
  execute function public.own_profile();

-- R4: Anonymous visitors cannot create or change profiles (enforced by own_profile function above)
-- No additional policy needed; the trigger blocks anon inserts/updates/deletes

-- R5: Service role bypasses RLS (already available, no grant needed)

-- Grants for authenticated users (optional, but common for application logic)
grant select, insert, update, delete on public.profiles to authenticated;
-- Service role already has full access by default
