create policy "Residents update plate only" on public.permits
  for update using (
    auth.role() = 'authenticated'
    and exists (select 1 from public.residents where unit_id = permits.unit_id and user_id = auth.uid())
  )
  with check (
    plate = old.plate -- allow plate update, but block validity/revoke changes by only checking plate in with check
    -- Note: we permit the plate column update; other columns must remain unchanged
    -- We enforce immutability of validity/revoke via a trigger below
  );

-- R4: HOA admins can revoke any permit; nobody can un-revoke; permits never deleted
create policy "HOA admins revoke permit" on public.permits
  for update using (
    auth.role() = 'service_role' or exists (select 1 from public.hoa_admins where user_id = auth.uid())
  )
  with check (
    revoked = true
  );

-- Prevent un-revoking and changes to validity/revoked via trigger
create function public.prevent_permit_modifications()
returns trigger
language plpgsql
security definer
as $$
begin
  -- Allow HOA admins and service role to set revoked=true, but never allow setting revoked=false
  if new.revoked = false and (auth.role() != 'service_role' and not exists (select 1 from public.hoa_admins where user_id = auth.uid())) then
    raise exception 'Cannot un-revoke a permit';
  end if;

  -- Residents and others cannot change validity or revoke status
  if new.valid_until != old.valid_until then
    raise exception 'Cannot change validity date';
  end if;

  if new.revoked != old.revoked and not (auth.role() = 'service_role' or exists (select 1 from public.hoa_admins where user_id = auth.uid())) then
    raise exception 'Only HOA admins or service role can change revoked status';
  end if;

  return new;
end;
$$;

create trigger prevent_permit_modifications_trigger
  before update on public.permits
  for each row
  execute function public.prevent_permit_modifications();

-- R5: Anonymous visitors cannot see or change anything (RLS default denies anon)
-- R6: Server-side code using service role keeps full access (already granted via policies using auth.role() = 'service_role')

-- Grants: ensure service_role has full access (already implicit, but explicit for clarity)
grant all on public.permits to service_role;
grant all on public.residents to service_role;
grant all on public.hoa_admins to service_role;
grant usage, select on sequence public.permits_id_seq to service_role;
